INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('consulta-general', 'Consulta general', 'estetoscopio', 'Valoramos el estado de salud de tu animal mediante un examen clínico y una evaluación profesional, brindándote orientación y recomendaciones para su bienestar.', '["perros","gatos","aves","roedores","bovinos","caprinos","ovinos","porcinos"]', 45, '45 min', 'domicilio', '{"tipo":"zona","bogota":85000,"fueraBogota":110000}', 1, 0);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('paseo-canino', 'Paseo canino', 'correa', 'Promovemos la actividad física, exploración y estimulación de tu perro mediante paseos adaptados a sus características y necesidades. Incluye hidratación, limpieza de pulpejos y cepillado.', '["perros"]', 90, '1 h 30 min (1 h de paseo + 30 min de cuidados)', 'domicilio', '{"tipo":"zona","bogota":40000,"fueraBogota":70000}', 1, 1);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('vacunacion', 'Vacunación', 'jeringa', 'Protegemos la salud de tu animal mediante la aplicación de vacunas y el seguimiento de esquemas de vacunación, de acuerdo con su edad, antecedentes y necesidades (esquema vacunal completo perros y gatos).', '["perros","gatos"]', 30, '30 min', 'domicilio', '{"tipo":"rango","desde":34900,"hasta":99300,"domicilioAparte":true}', 1, 2);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('toma-muestras', 'Toma de muestras de laboratorio', 'tubo', 'Realizamos la recolección de muestras biológicas para apoyar los procesos de diagnóstico, evaluación y seguimiento de la salud de tu animal.', '["perros","gatos","ovinos","caprinos","bovinos","porcinos","aves"]', 30, '30 min', 'domicilio', '{"tipo":"rango","desde":55600,"hasta":332400,"domicilioAparte":true}', 1, 3);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('asesoria-zootecnica', 'Asesoría presencial zootécnica', 'granero', 'Brindamos orientación profesional sobre alimentación, manejo, bienestar y productividad animal, buscando mejorar las condiciones de crianza y producción.', '["ovinos","caprinos","bovinos","porcinos","aves"]', 300, '2 a 5 horas', 'domicilio', '{"tipo":"fijo","valor":200000}', 1, 4);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('asesoria-nutricional', 'Asesoría virtual nutricional', 'plato', 'Ofrecemos orientación nutricional personalizada para ayudarte a elegir y ajustar la alimentación de tu animal según su especie, etapa de vida y necesidades particulares.', '["perros","gatos","aves","roedores"]', 30, '30 min (virtual)', 'virtual', '{"tipo":"fijo","valor":70000}', 1, 5);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('enriquecimiento', 'Asesoría presencial de enriquecimiento', 'pelota', 'Diseñamos recomendaciones y estrategias para estimular los comportamientos naturales de los animales, promover su actividad y mejorar su entorno y bienestar.', '["perros","gatos","ovinos","caprinos","porcinos","aves"]', 60, '1 hora', 'domicilio', '{"tipo":"fijo","valor":60000}', 1, 6);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('tratamientos-casa', 'Asistencia en tratamientos en casa', 'curita', 'Acompañamos los tratamientos prescritos por el médico veterinario mediante administración de medicamentos, curaciones sencillas, limpieza externa de oídos y ojos cuando esté indicada y seguimiento de tratamientos.', '["perros","gatos","ovinos","caprinos","porcinos","aves"]', 40, '40 min', 'domicilio', '{"tipo":"zona","bogota":55000,"fueraBogota":80000}', 1, 7);
INSERT INTO servicios (id, nombre, icono, descripcion, especies, duracion_min, duracion_texto, modalidad, precio, visible, orden) VALUES ('neonatologia', 'Asistencia en neonatología', 'biberon', 'Acompañamiento y cuidado de animales recién nacidos mediante orientación en alimentación, estimulación para la eliminación de heces y valoración clínica, para favorecer su desarrollo y bienestar en esta etapa.', '["perros","gatos","porcinos","aves"]', 60, '1 hora', 'domicilio', '{"tipo":"zona","bogota":120000,"fueraBogota":150000}', 1, 8);
